async fn seq_continues_across_resume_seed() {
    let s = SqliteStore::open_in_memory().unwrap();
    use bridge_core::ids::NodeId;
    let t = TaskId::parse("t").unwrap();
    s.create(&trec("t", 1)).await.unwrap();
    let op = OperationId::parse("op-t").unwrap();
