            &NodeId::parse("a").unwrap(),
            &op,
            "A",
            true,
            1,
            None,
        )
        .await
        .unwrap();
    let b = s
        .record_node_started(&t, &NodeId::parse("b").unwrap(), &op, 2)
        .await
        .unwrap();
    assert!(b > a, "seq continues across a resumed run, not reset");
}

