    #[tokio::test]
    async fn sqlite_list_and_active_batches() {
        let s = SqliteStore::open_in_memory().unwrap();
        let working = BatchId::parse("b-working").unwrap();
        let canceling = BatchId::parse("b-canceling").unwrap();
        let done = BatchId::parse("b-done").unwrap();
        s.create_batch(&sample_batch(&working, BatchStatus::Working, 1, 1))
            .await
            .unwrap();
        s.create_batch(&sample_batch(&canceling, BatchStatus::Canceling, 1, 2))
            .await
            .unwrap();
        s.create_batch(&sample_batch(&done, BatchStatus::Completed, 1, 3))
            .await
            .unwrap();

        let listed = s.list_batches(10).await.unwrap();
        assert_eq!(listed.len(), 3, "list_batches returns every batch");
        assert_eq!(
            listed[0].id, done,
            "list_batches orders newest (highest updated_ms) first"
        );

        let mut active: Vec<BatchId> =
            s.active_batches().await.unwrap().into_iter().map(|b| b.id).collect();
